import{describe,expect,it,vi,afterEach}from'vitest';
import{createHash}from'node:crypto';
import{candidateCompanies}from'../../src/data/companyRegistry';
import{buildStagedSourceCrawlPlans}from'../../src/crawler/sourcePlan';
import{createOwnedSourceQualityFetch,getSourceQualityPolicy,sourceQualityPageBodiesMatchFingerprints}from'../../src/crawler/sourceQualityAdmission';
import type{PersistentSourceFetchEvidence}from'../../src/crawler/sourceFetchEvidence';
const plans=buildStagedSourceCrawlPlans(candidateCompanies);
afterEach(()=>vi.unstubAllGlobals());
describe('independently reviewed HTML registrations',()=>{
 it.each(['source-abbvie-china-social','source-novartis-social','source-takeda-china-social','source-viatris-social','source-astellas-china-social','source-kelun-social'])('admits only the exact reviewed %s configuration',id=>{const p=structuredClone(plans.find(p=>p.source.id===id)!);expect(getSourceQualityPolicy(p)).toBe('PLAN_BOUND_SOURCE_QUALITY_V1');p.source.officialEntryUrl+='&changed=1';expect(getSourceQualityPolicy(p)).toBeNull();});
 it.each(['source-sanofi-china-social','source-grand-pharma-social'])('withholds %s on the actual source-quality gap',id=>{expect(getSourceQualityPolicy(plans.find(p=>p.source.id===id)!)).toBeNull();});
 it('uses the existing ordinary HTML fetcher rather than a browser or unsupported fallback',async()=>{const p=plans.find(p=>p.source.id==='source-kelun-social')!;const fetch=vi.fn(async(url:string)=>({status:503,url,headers:new Headers({'content-type':'text/html'}),text:async()=>'<h1>temporarily unavailable</h1>'}));vi.stubGlobal('fetch',fetch);const r=await createOwnedSourceQualityFetch()(p);expect(r.ok).toBe(false);expect(fetch).toHaveBeenCalledOnce();expect(fetch.mock.calls[0]![0]).toBe(p.source.officialEntryUrl);});
 it('independently binds every page fingerprint to its exact stored response bytes',()=>{const body='<div>original public job body</div>';const e={pages:[{artifactLogicalKey:'p',responseFingerprintSha256:createHash('sha256').update(body).digest('hex')}],artifacts:[{logicalKey:'p',body,bodyRepresentation:'EXACT'}]} as PersistentSourceFetchEvidence;expect(sourceQualityPageBodiesMatchFingerprints(e)).toBe(true);const bad=structuredClone(e);bad.pages[0]!.responseFingerprintSha256='f'.repeat(64);expect(sourceQualityPageBodiesMatchFingerprints(bad)).toBe(false);bad.pages[0]!.responseFingerprintSha256=e.pages[0]!.responseFingerprintSha256;bad.artifacts[0]!.body='modified';expect(sourceQualityPageBodiesMatchFingerprints(bad)).toBe(false);});
 it('rejects missing, duplicate or non-exact page bodies',()=>{const body='{}';const e={pages:[{artifactLogicalKey:'p',responseFingerprintSha256:createHash('sha256').update(body).digest('hex')}],artifacts:[{logicalKey:'p',body,bodyRepresentation:'EXACT'}]} as PersistentSourceFetchEvidence;expect(sourceQualityPageBodiesMatchFingerprints({...e,artifacts:[]})).toBe(false);expect(sourceQualityPageBodiesMatchFingerprints({...e,artifacts:[e.artifacts[0]!,e.artifacts[0]!]})).toBe(false);const redacted=structuredClone(e);redacted.artifacts[0]!.bodyRepresentation='REDACTED';expect(sourceQualityPageBodiesMatchFingerprints(redacted)).toBe(false);});
});
